package io.knowledgebrain.space;
import java.time.*;import java.util.*;
import org.flywaydb.core.Flyway;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;
import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_SPACE_DATABASE_URL",matches=".+")
class PublicRoadmapAuthorizationIntegrationTest {
 MockHttpServletRequest request(){var r=new MockHttpServletRequest();r.setSecure(true);r.addHeader("Authorization","Bearer "+"a".repeat(43));return r;}
 @Test void publicRoadmapsReuseLiveOperatorMembershipButNeverPrivatePermissions(){var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_SPACE_DATABASE_URL"));ds.setUser("brain_space");ds.setPassword(System.getenv("BRAIN_TEST_SPACE_DATABASE_PASSWORD"));Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();var sql=new JdbcTemplate(ds);var spaces=mock(PersonalSpaceStore.class);var identity=mock(IdentityPrincipalClient.class);var api=new LearningAuthorizationController(spaces,identity,"a".repeat(43));api.dataSource=ds;UUID actor=new UuidV7(Clock.systemUTC()).next(),space=UUID.fromString("0199e000-0000-7000-8000-000000000002");var guest=new IdentityPrincipalClient.Principal(actor,"GUEST",Instant.now().plusSeconds(60));var account=new IdentityPrincipalClient.Principal(actor,"REGISTERED",guest.expiresAt());when(identity.resolve("b".repeat(43),null)).thenReturn(guest);assertEquals("PUBLIC",api.authorize(new LearningAuthorizationController.Check(space,"b".repeat(43),"PUBLIC_ROADMAP_READ"),request()).getBody().visibility());for(String action:List.of("ROADMAP_PROPOSE","ROADMAP_REVIEW","ROADMAP_MERGE","ROADMAP_RATE","ROADMAP_RATING_READ"))assertEquals(403,assertThrows(ResponseStatusException.class,()->api.authorize(new LearningAuthorizationController.Check(space,"b".repeat(43),action),request())).getStatusCode().value());when(identity.resolve("b".repeat(43),null)).thenReturn(account);for(String action:List.of("ROADMAP_PROPOSE","ROADMAP_RATING_READ","ROADMAP_RATE"))assertEquals(actor,api.authorize(new LearningAuthorizationController.Check(space,"b".repeat(43),action),request()).getBody().principalId());assertThrows(ResponseStatusException.class,()->api.authorize(new LearningAuthorizationController.Check(space,"b".repeat(43),"ROADMAP_REVIEW"),request()));sql.update("INSERT INTO space_membership(space_id,principal_id,role) VALUES (?,?,'REVIEWER')",space,actor);try{for(String action:List.of("ROADMAP_REVIEW","ROADMAP_MERGE"))assertEquals(action,api.authorize(new LearningAuthorizationController.Check(space,"b".repeat(43),action),request()).getBody().action());sql.update("UPDATE space_membership SET state='RETIRED' WHERE space_id=? AND principal_id=?",space,actor);assertEquals(403,assertThrows(ResponseStatusException.class,()->api.authorize(new LearningAuthorizationController.Check(space,"b".repeat(43),"ROADMAP_MERGE"),request())).getStatusCode().value());}finally{sql.update("DELETE FROM space_membership WHERE space_id=? AND principal_id=?",space,actor);}verifyNoInteractions(spaces);}
}
